@once
<style>
.audit-create-button{border:0;border-radius:8px;padding:10px 16px;background:var(--green,var(--brand,#1a4d3a));color:#fff;font:inherit;font-weight:700;cursor:pointer;white-space:nowrap}.audit-create-dialog{margin:auto;border:0;border-radius:14px;padding:24px;width:min(900px,calc(100vw - 32px));max-height:90vh;box-sizing:border-box;overflow:auto}.audit-create-dialog::backdrop{background:rgba(0,0,0,.45)}.audit-create-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.audit-create-field{display:flex;flex-direction:column;gap:6px;min-width:0}.audit-create-field.full{grid-column:1/-1}.audit-create-field label{font-size:13px;font-weight:700}.audit-create-field input:not([type=checkbox]),.audit-create-field select,.audit-create-field textarea{box-sizing:border-box;width:100%;border:1px solid #d8d4ca;border-radius:7px;padding:9px;font:inherit}.audit-create-members{max-height:150px;overflow:auto;border:1px solid #d8d4ca;border-radius:7px;padding:8px}.audit-create-members label{display:block;font-weight:400;margin:5px}.audit-create-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}@media(max-width:600px){.audit-create-fields{grid-template-columns:1fr}}
</style>
@endonce
